# Second metadata table (22 descriptive columns) for the Batch5 records that contain spectra.
# Field keys (see DETAIL_COLUMNS in curation/build.py):
# fmt, npts, missing, prep, prep_methods, target, mode, wl, res, make, path, ts, chemo, refs,
# remarks, cond, absorb, refm, gold, peaks, struct
NR = "Not reported"
NA = "Not applicable"
R2 = {}


def rec(rid, **k):
    R2[rid] = k


