_IODP_REF = {
    395: "Parnell-Turner, Briais, LeVay & Expedition 395 Scientists (2025) Reykjanes Mantle Convection and Climate, Proc. IODP 395 (Expeditions 384, 395C, 395), doi:10.14379/iodp.proc.395.2025",
    401: "Flecker, Ducassou, Williams & Expedition 401 Scientists (2025) Mediterranean-Atlantic Gateway Exchange, Proc. IODP 401, doi:10.14379/iodp.proc.401.2025",
    402: "Zitellini, Malinverno, Estes & Expedition 402 Scientists (2025) Tyrrhenian Continent-Ocean Transition, Proc. IODP 402, doi:10.14379/iodp.proc.402.2025",
}
_IODP_PAPER = {
    395: "Vol. 395 front matter (HAL hal-05384185; title page, publisher notes, contents - no RSC/SPEC results)",
    401: "Vol. 401 front matter/table of contents only",
    402: "Vol. 402 front matter/table of contents only",
}
_SPEC_REAGENT = {
    "ammonium": "ammonium: phenol-hypochlorite indophenol blue",
    "phosphate": "phosphate: ammonium molybdate / ascorbic acid molybdenum blue",
    "silica": "silica: molybdate / metol-sulfite (molybdenum blue)",
    "sulfide": "sulfide: N,N-dimethyl-p-phenylenediamine / FeCl3 methylene blue",
}
_SPEC_STRUCT = {
    "ammonium": "ammonium [NH4+]",
    "phosphate": "phosphate [O-]P(=O)([O-])[O-]",
    "silica": "silicic acid O[Si](O)(O)O",
    "sulfide": "hydrogen sulfide [SH-]/S",
}


def _spec2(rid, exp, vol, counts, nsamples, nholes, fmt, missing, extra_remark=""):
    wl = {"ammonium": "640", "phosphate": "885", "silica": "812", "sulfide": "670"}
    analytes = list(counts)
    rec(rid,
        fmt=fmt,
        npts=f"{sum(counts.values())} concentration results (" + ", ".join(f"{a} {n}" for a, n in counts.items()) + f") for {nsamples} IW samples in {nholes} holes; standard/sample absorbance readings in supplementary files",
        missing=missing,
        prep="Yes (absorbance converted to concentration via standard curve)",
        prep_methods="1) IW subsample diluted and reacted with colour reagent (" + "; ".join(_SPEC_REAGENT[a] for a in analytes) + "); 2) absorbance read at fixed wavelength (Cary Advanced Reads); 3) linear calibration against standard series; 4) dilution correction",
        target="Dissolved " + ", ".join(analytes) + " concentration in interstitial water vs depth",
        mode="Single-wavelength absorbance (double-beam UV-Vis, cuvette)",
        wl="; ".join(f"{a} {wl[a]}" for a in analytes),
        res="Spectral bandwidth 1.5 nm (Advanced Reads reports)",
        make="Agilent Cary 300 UV-Vis (Advanced Reads 4.20; README says Cary 100)",
        path="1 cm cuvette (standard; not stated in dataset)",
        ts="No (depth series)",
        chemo="No (univariate linear calibration)",
        refs=_IODP_REF[vol],
        remarks=f"Paper PDF is the {_IODP_PAPER[vol]}; Exp {exp}; data_by_hole tables give Analyte, Concentration (uM), Text ID, Test No., comments" + extra_remark,
        cond="Shipboard laboratory, room temperature colour development",
        absorb="Linear absorbance-concentration calibration slopes in calibration workbooks",
        refm="Gravimetric standard series (LVL 0-8000 STD) and check standards",
        gold=NA, peaks=NA,
        struct="; ".join(_SPEC_STRUCT[a] for a in analytes) + "; indophenol blue / molybdenum blue" + (" / methylene blue" if "sulfide" in analytes else "") + " chromophores")


