def _rsc2(rid, exp, vol, nspectra, nfiles, nsections, nreduced, sensor, missing, extra_remark=""):
    rec(rid,
        fmt="Folder: data_by_hole per-hole CSV (L*, a*, b*, XYZ, file names, timestamps, instrument) + data_by_hole_scaled (CCSF) / compiled_scales / splice variants; supplementary_material raw_data_files per section (norm_*_rsc.csv % reflectance with X,Y,Z,L*,a*,b*, chroma, hue, sensor temperature and 165 spectral columns; raw_*_rsc.csv counts; *.RSC headers), configuration_files (*.ini), standards_measured; RSC-README.txt; site-location HTML",
        npts=f"{nspectra:,} reflectance spectra x 165 bands (390-718 nm, 2 nm) = {nspectra * 165:,} values in {nfiles:,} normalised files ({nsections:,} section halves); {nreduced:,} reduced colour rows",
        missing=missing,
        prep="Yes (white/dark normalisation in norm files; raw counts also given)",
        prep_methods="1) Dark and white reference correction -> % reflectance; 2) spectra binned (2 nm); 3) CIE XYZ tristimulus and L*a*b*, chroma, hue computed; 4) white standard measured (standards_measured)",
        target="Sediment/rock colour (lightness L*, a*, b*) down-core for lithostratigraphy and correlation",
        mode="Diffuse reflectance with integrating sphere in contact with split-core surface covered by clear film, Section Half Multisensor Logger (SHMSL)",
        wl="390-718 (2 nm bins; README states 380-700)",
        res="Not reported (2 nm binning)",
        make=f"{sensor} spectrometer + integrating sphere on SHMSL",
        path=NA,
        ts="No (depth series; typically 2-5 cm spacing)",
        chemo="No",
        refs=_IODP_REF[vol],
        remarks=f"Paper PDF is the {_IODP_PAPER[vol]}; Exp {exp}" + extra_remark,
        cond="Shipboard core laboratory; split section halves at room temperature, measured shortly after splitting",
        absorb=NA,
        refm="White and dark calibration references; white standard spectrum file",
        gold=NA,
        peaks="Broad VIS slopes: Fe-oxide absorption (<550 nm, raises a*/b*), organic matter/sulfides darken (low L*), carbonate/biosiliceous ooze bright (high L*); basalt basement dark",
        struct=NA)


